from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from rest_framework.exceptions import PermissionDenied
from django.shortcuts import get_object_or_404
from .models import UserProfile

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def revert_user_profile(request):
    history_id = request.data.get('history_id')
    if not history_id:
        return Response({'error': 'history_id is required'}, status=status.HTTP_400_BAD_REQUEST)

    historical_record = get_object_or_404(UserProfile.history.model, history_id=history_id)
    if historical_record.user != request.user and not request.user.is_superuser:
        raise PermissionDenied("You can only revert your own profile revisions.")

    historical_record.instance.save()

    return Response({
        'status': 'reverted',
        'profile_id': historical_record.id,
        'reverted_to_date': historical_record.history_date
    })
